DROP TABLE IF EXISTS public.md_customers CASCADE;

CREATE TABLE public.md_customers (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code varchar(50) NOT NULL UNIQUE,
    name varchar(200) NOT NULL,
    short_name varchar(100) NOT NULL DEFAULT '',
    industry varchar(100) NOT NULL DEFAULT '',
    level varchar(20) NOT NULL DEFAULT 'normal',
    contact_person varchar(100) NOT NULL DEFAULT '',
    contact_phone varchar(50) NOT NULL DEFAULT '',
    contact_email varchar(100) NOT NULL DEFAULT '',
    address varchar(500) NOT NULL DEFAULT '',
    credit_limit numeric(16,2) NOT NULL DEFAULT 0,
    credit_used numeric(16,2) NOT NULL DEFAULT 0,
    status smallint NOT NULL DEFAULT 1,
    created_by bigint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    business_tenant_id bigint NOT NULL CHECK (business_tenant_id > 0)
);

